// 取得輸入資料
const data = $('XML to Json').first().json;
// 展開所有比賽並只提取需要的欄位
const output = [];

// 建立 league ID 到完整 league info 的映射
const leagueMap = {};
const eventStatusMap = {};

if (data.F24?.Kraje?.K && Array.isArray(data.F24.Kraje.K)) {
  data.F24.Kraje.K.forEach(country => {
    const countryName = country.KN || '';

    // 處理 L 可能是陣列或單一物件的情況
    const leagues = Array.isArray(country.L) ? country.L : [country.L];

    leagues.forEach(league => {
      if (league?.LId && league?.LN) {
        // 儲存主聯賽資訊
        leagueMap[league.LId] = {
          country: countryName,
          league: league.LN,
          subLeague: ''
        };

        // 處理子聯賽 (PL 可能是陣列或單一物件)
        if (league.PL) {
          const subLeagues = Array.isArray(league.PL) ? league.PL : [league.PL];

          subLeagues.forEach(subLeague => {
            if (subLeague?.LId && subLeague?.LN) {
              leagueMap[subLeague.LId] = {
                country: countryName,
                league: league.LN,
                subLeague: subLeague.LN
              };
            }
          });
        }
      }
    });
  });
}

// 建立 match ID 到 event status 的映射
if (data.F24?.Zd?.Z && Array.isArray(data.F24.Zd.Z)) {
  data.F24.Zd.Z.forEach(eventStatus => {
    if (eventStatus.MId && eventStatus.CM) {
      const matchId = eventStatus.MId;
      const eventInfo = eventStatus.CM;

      // 直接覆蓋，最後一個會保留
      eventStatusMap[matchId] = eventInfo;
    }
  });
} // ✅ 只要一個 }

// 檢查並展開 Mecze 陣列
if (data.F24?.Mecze?.M && Array.isArray(data.F24.Mecze.M)) {
  data.F24.Mecze.M.forEach(match => {
    var eventTimeStamp = match.C0 || '';
    const date = new Date((eventTimeStamp * 1000) + (8 * 60 * 60 * 1000));
    const eventDate = date.toISOString().split('T')[0];
    const eventTime = date.toISOString().slice(0, 19);

    // 優先使用 LId (子聯賽),如果沒有則使用 _LId (主聯賽)
    const leagueId = match.LId || match._LId || '';
    const leagueInfo = leagueMap[leagueId] || { country: '', league: '', subLeague: '' };

    output.push({
      json: {
        Cid: match.KId,
        CName: leagueInfo.country || '',
        MId: match.MId || '',
        EventDate: eventDate,
        EventTime: eventTime,
        PLeagueId: match._LId,
        LeagueId: match.LId,
        PLeagueName: leagueInfo.league || "",
        LeagueName: leagueInfo.subLeague || "",
        HomeId: match.HId,
        HomeName: match.HN || '',
        AwayId: match.GId,
        AwayName: match.GN || '',
        EventStatus: match.MStan,
        FScore: match.S1 || '',
        HScore: match.S2 || '',
        HRedCard: match.HRCi || '',
        ARedCard: match.GRCi || '',
      }
    });
  });
}

return output;

// Format date as yyyyMMdd
const formatDate = (date) => {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${year}${month}${day}`;
};

// Get today's date
const today = new Date();

// Build URL array
const urls = [];

// Generate URLs for the next 14 days
for (let i = 0; i < 2; i++) {
  const date = new Date(today);
  date.setDate(today.getDate() + i);
  urls.push('https://www.futbol24.com/matchDayXml/?Day=' + formatDate(date));
}

// Add live now URL
urls.push('https://p.futbol24.com/f24/u/liveNow_15.xml');

// Return URLs for n8n
return urls.map(url => ({ json: { url } }));
